func uniquePaths(m int, n int) int {
	dp := make([][]int, m)
	for i := range dp {    // 第一行、第一列都只有 1 种走法
		dp[i] = make([]int, n)
		for j := range dp[i] {
			dp[i][j] = 1
		}
	}
	for i := 1; i < m; i++ {
		for j := 1; j < n; j++ {
			dp[i][j] = dp[i-1][j] + dp[i][j-1] // 从上面来 + 从左边来
		}
	}
	return dp[m-1][n-1]
}

